def nw(s1,s2,go=-11.0,ge=-1.0):
    n,m=len(s1),len(s2); NEG=-1e7; sub=MAT[np.ix_(enc(s1),enc(s2))]
    M=np.full((n+1,m+1),NEG);Ix=np.full((n+1,m+1),NEG);Iy=np.full((n+1,m+1),NEG)
    PM=np.zeros((n+1,m+1),np.int8);PX=np.zeros((n+1,m+1),np.int8);PY=np.zeros((n+1,m+1),np.int8)
    M[0,0]=0
    for i in range(1,n+1): Ix[i,0]=go+ge*(i-1);PX[i,0]=1
    for j in range(1,m+1): Iy[0,j]=go+ge*(j-1);PY[0,j]=2
    ar=np.arange(m)
    for i in range(1,n+1):
        pv=np.vstack([M[i-1,:-1],Ix[i-1,:-1],Iy[i-1,:-1]]);k=pv.argmax(0)
        M[i,1:]=pv[k,ar]+sub[i-1];PM[i,1:]=k
        v=np.vstack([M[i-1,1:]+go,Ix[i-1,1:]+ge]);k2=v.argmax(0)
        Ix[i,1:]=v[k2,ar];PX[i,1:]=np.where(k2==0,0,1);Ix[i,0]=go+ge*(i-1)
        rM=M[i];rI=Iy[i];rP=PY[i]
        for j in range(1,m+1):
            a0=rM[j-1]+go;a1=rI[j-1]+ge
            if a0>=a1: rI[j]=a0;rP[j]=0
            else: rI[j]=a1;rP[j]=2
    i,j=n,m;st=int(np.argmax([M[n,m],Ix[n,m],Iy[n,m]]));A=[];B=[]
    while i>0 or j>0:
        if i==0: A.append('-');B.append(s2[j-1]);j-=1;continue
        if j==0: A.append(s1[i-1]);B.append('-');i-=1;continue
        if st==0: A.append(s1[i-1]);B.append(s2[j-1]);st=PM[i,j];i-=1;j-=1
        elif st==1: A.append(s1[i-1]);B.append('-');st=PX[i,j];i-=1
        else: A.append('-');B.append(s2[j-1]);st=PY[i,j];j-=1
    return "".join(reversed(A)),"".join(reversed(B))
